def rle_encode(s):
    """Run-length encodes a string as character followed by count."""
    if not s:
        return ""
    prev = s[0]
    count = 1
    encoded = []
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            encoded.append(f"{prev}{count}")
            prev = c
            count = 1
    encoded.append(f"{prev}{count}")
    return "".join(encoded)

