def is_valid_ipv4(s):
    """Return True if the string is a valid IPv4 address."""
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if part == '0' or (part[0] != '0' and part[0].isdigit()):
            continue
        else:
            return False
    return True

